#include <stdio.h>
#include <stdlib.h>

int main(void) {
    FILE *log_file = NULL;
    int error_code = 503;
    const char *service = "AuthGateway";

    // 1. Open a file stream for logging
    log_file = fopen("server_status.log", "a"); // 'a' for append
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Could not open log file.\n");
        return EXIT_FAILURE;
    }

    // 2. Use fprintf to write formatted data to the file stream
    int chars_written = fprintf(log_file, 
                                "[%s] Error %d: Service unavailable or timed out.\n", 
                                service, error_code);

    // 3. Check the return value for errors during writing
    if (chars_written < 0) {
        fprintf(stderr, "[WARNING] Failed to write log entry. (I/O error)\n");
    } else {
        // 4. Use fprintf to write confirmation to the standard error stream
        fprintf(stderr, "Wrote %d characters to log file successfully.\n", chars_written);
    }

    // 5. Cleanup
    if (fclose(log_file) == EOF) {
        fprintf(stderr, "Error closing file stream.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
